  var P = (u && DEPT_PROF[u]) || { t1: [], t2: [], cases: [] }, ids = {};
  us.forEach(function (uu) { var PP = DEPT_PROF[uu] || { t1: [], t2: [] }; (DB.nunitIds(uu, S.level) || []).forEach(function (id) { ids[id] = 1; }); PP.t1.concat(PP.t2).forEach(function (id) { ids[id] = 1; }); });
