/* ---------- protocols side tab ---------- */
var P = { open: false, type: "EMS", state: (store("settings") || {}).state || "", agency: "", checked: false, form: { name: "", email: "", notes: "" }, saved: null, inbox: null, owner: false, db: null, uid: null };
