  var c = '<div class="pbar"><h2>Protocols</h2><button class="theme-btn" data-pact="close">Close</button></div>';
  if (typeof agpCard === "function") { if (AGP.data && typeof AGQ !== "undefined" && AGQ.on) return c + agqView(); if (AGP.view && AGP.data) return c + agpPage(); c += agpCard(); }
  c += '<p class="muted">See if your state or agency protocols are already in DrugBug. If they are not, send them in and we will add them.</p>';
  c += '<div class="pform"><label>Type<select class="pinput" id="ptype">' + ["EMS", "Nursing", "Hospital", "Med school"].map(function (t) { return '<option' + (P.type === t ? " selected" : "") + '>' + t + '</option>'; }).join("") + '</select></label>';
  c += '<label>State<select class="pinput" id="pstate"><option value="">Choose a state</option>' + DB.STATES.map(function (x) { return '<option value="' + x[0] + '"' + (P.state === x[0] ? " selected" : "") + '>' + x[1] + '</option>'; }).join("") + '</select></label>';
  c += '<label>Agency, facility or school<input class="pinput" id="pagency" type="text" placeholder="e.g. Austin-Travis County EMS" value="' + esc(P.agency) + '"></label>';
  c += '<button class="btn" data-pact="check"' + (P.state ? "" : " disabled") + '>Check my protocols</button></div>';
  if (P.checked) {
    var m = protoMatches();
    if (m.length) {
      c += '<div class="presult good"><strong>Good news: these are in DrugBug.</strong><ul>' + m.map(function (p) { return '<li>' + esc(p.name) + ' (' + esc(stateName(p.state)) + ')' + (p.note ? ' – ' + esc(p.note) : '') + (p.id ? ' <span class="muted small">Used with permission.</span>' : '') + (p.id ? (store("protocol") === p.id ? ' <strong>In use</strong>' : ' <button class="btn small" data-pact="use" data-pid="' + esc(p.id) + '">Use these protocols</button>') : '') + '</li>'; }).join("") + '</ul></div>';
    } else {
      c += '<div class="presult"><strong>Not in DrugBug yet.</strong> ' + esc(P.agency || "Your agency") + ' (' + esc(stateName(P.state)) + ') protocols have not been added. Send them in below.</div>';
      c += !HASDB ? '<p class="muted small">Email us a link or photos of your protocols and we will add them.</p><a class="btn" href="' + esc(protoMail()) + '">Email your protocols</a>' : pqForm();
    }
  }
  c += '<h3 class="eh small">What DrugBug uses now (' + esc(P.type) + ')</h3><ul class="plist">' + nat.map(function (p) { return '<li><strong>' + esc(p.name) + '</strong><br><span class="muted small">' + esc(p.note) + '</span></li>'; }).join("") + '</ul>';
