// Sticks per correct answer, by the level of the question. Higher scope pays more.
var STICKV = { emt: 1, cna: 1, aemt: 1, lvn: 1, gen: 1, paramedic: 1, rn: 1, ms1: 1, flight: 1, ms3: 1, intern: 1 };
var PERFECT_BONUS = 10, ACH_BONUS = 25;
function perfectBonus(st, total, correct) { if (st.perfectPaid || total < 10 || correct !== total) return false; st.perfectPaid = true; earn(PERFECT_BONUS); saveProg(); return true; }
var START_STICKS = 20;
/* earned on the device + paid for on the server, less what has been spent (modules/wallet.js) */
function sticksRaw() { var P = Prog.d; return START_STICKS + (P.earned || 0) + (typeof walletSticks === "function" ? walletSticks() : 0) - (P.spent || 0); }
/* never shows a debt (owner, Nov 12 2026: a signed-in account showed -3,992) */
function sticks() { return Math.max(0, sticksRaw()); }
/* A balance below zero is never something the person did: every purchase checks the balance first.
   It comes from sync, usually purchased sticks spent under one account or browser and then counted
   without that wallet (a different account signed in on the same browser, or a cached wallet).
   Once the real wallet has answered, forgive the gap by raising earned, which syncs (max-merge)
   instead of being undone by the other device. Logged in Prog.d.stickFix. */
function stickRepair() {
  var raw = sticksRaw(); if (raw >= 0) return;
  var P = Prog.d, gap = -raw; P.earned = (P.earned || 0) + gap;
  P.stickFix = (P.stickFix || []).concat([{ at: Date.now(), n: gap }]).slice(-10);
  if (typeof saveProg === "function") saveProg();
}
var STICK_TRY = 1, STICK_RIGHT = 3; /* every answered question pays 1 stick for trying, 3 when correct */
/* the peeking pal riding with your bug adds sticks to every right answer (owner, Nov 5 2026).
   Every level up now adds one more (owner, Nov 7 2026): +1 at level 1, +2 at level 2 ... +10 at
   level 10. It used to step only at levels 5 and 10. */
/* Nov 18 2026 (owner): one more stick every other level, capped at +5 (levels 1-2 +1, 3-4 +2 ... 9 and up +5) */
function palBonusAt(lv) { return Math.max(1, Math.min(5, Math.ceil((lv || 1) / 2))); }
function palBonus() { var id = Prog.d.pal; if (!id || typeof pkCaught !== "function" || !pkCaught(id)) return 0; return palBonusAt(typeof pkLv === "function" ? pkLv(id) : 1); }
function qSticks(ok) { return ok ? STICK_RIGHT + palBonus() : STICK_TRY; }
function stickNote(ok) { var n = qSticks(ok), pb = ok ? palBonus() : 0; return ' <span class="earned">+' + n + (n === 1 ? " stick" : " sticks") + (ok ? "" : " for trying") + (pb ? ' (' + pb + ' from your pal)' : '') + '</span>'; }
function earn(n) { if (!n) return; var P = Prog.d; P.earned = (P.earned || 0) + n; }
