var LANG_C = null;
function lang() { return "en"; }  /* Spanish removed Oct 26, 2026 (owner decision); DB.ES is kept only for pronunciations */
function langBtn() { return '<button class="theme-btn" data-act="lang" lang="' + (lang() === "es" ? "en" : "es") + '" aria-label="' + (lang() === "es" ? "Switch to English" : "Cambiar a español") + '">' + (lang() === "es" ? "English" : "Español") + '</button>'; }
function setLang(l) { return; /* Spanish removed */  store("lang", l); LANG_C = null; document.documentElement.lang = l; render(); if (S.sheet) drawSheet(); if (P.open) drawProto(); }
var ES_RX = [
  [/^Please read \((\d+)\)$/, "Lea por favor ($1)"],
  [/^(\d+) drugs in scope$/, "$1 medicamentos en su nivel"], [/^(\d+) drugs?$/, "$1 medicamentos"], [/^(\d+) medications$/, "$1 medicamentos"],
  [/^Level (\d+) of (\d+)$/, "Nivel $1 de $2"], [/^LEVEL (\d+) OF (\d+)$/, "NIVEL $1 DE $2"], [/^Question (\d+) of (\d+)$/, "Pregunta $1 de $2"],
  [/^(\d+) EMS drugs$/, "$1 medicamentos de EMS"], [/^(\d+) nursing drugs$/, "$1 medicamentos de enfermería"], [/^(\d+) saved drugs$/, "$1 medicamentos guardados"],
  [/^(.+) \((\d+)\)$/, function (m, g, n) { return ES_GROUPS[g] ? ES_GROUPS[g] + " (" + n + ")" : m; }], [/^Need (\d+) more$/, "Faltan $1"], [/^(\d+) of (\d+) scenarios cleared$/, "$1 de $2 casos superados"], [/^(\d+)% mastered · (\d+) of (\d+) drugs$/, "$1% dominado · $2 de $3 medicamentos"],
  [/^Card (\d+) of (\d+)$/, "Tarjeta $1 de $2"], [/^Mastered (\d+) \/ (\d+)$/, "Dominadas $1 / $2"], [/^of (\d+) drugs$/, "de $1 medicamentos"], [/^(\d+) decisions$/, "$1 decisiones"], [/^best (\d+) days$/, "mejor: $1 días"], [/^Challenge: 5 (.+) questions$/, function (m, g) { return "Reto: 5 preguntas de " + (ES_GROUPS[g] || g); }],
  [/^(\d+)-day streak · Level (\d+) · ([\d,]+) XP$/, "Racha de $1 días · Nivel $2 · $3 XP"], [/^(.+) · (\d+) drugs in scope$/, "$1 · $2 medicamentos en su nivel"], [/^Everything \((\d+)\)$/, "Todo ($1)"],
  [/^My List \((\d+)\)$/, "Mi lista ($1)"], [/^([\d,–]+) sticks$/, "$1 palitos"], [/^(\d+) of (\d+) owned$/, "$1 de $2 comprados"], [/^([\d,]+) sticks, only in season$/, "$1 palitos, solo en temporada"], [/^(\d+) questions on your weak areas, then one clinical scenario\.$/, "$1 preguntas sobre sus puntos débiles y luego un caso clínico."], [/^Showing as (.+)\.$/, "Aparece como $1."], [/^In (\d+) class(es)?\. Instructors see this name\.$/, "En $1 clase(s). Los instructores ven este nombre."], [/^(\d+) of (\d+) drugs clinically reviewed so far; (\d+) verified by a pharmacist or physician\.$/, "$1 de $2 medicamentos con revisión clínica hasta ahora; $3 verificados por un farmacéutico o médico."], [/^Clinically reviewed \((.+)\)$/, "Con revisión clínica ($1)"],
  [/^(.+)-style multiple choice on the medications\. Pick a length and a mode, then start\. Questions are drawn at random from your level( and below)?\.$/, function (m, ex, below) { return "Opción múltiple estilo " + ex + " sobre los medicamentos. Elija la cantidad y el modo, y empiece. Las preguntas salen al azar de su nivel" + (below ? " y los anteriores" : "") + "."; }],
  [/^Original practice questions written for studying, not official (.+) items\. Aim for steady scores of 70% or better here\.$/, "Preguntas originales de práctica para estudiar; no son preguntas oficiales de $1. Busque mantener 70% o más."],
  [/^Start (\d+) questions$/, "Empezar $1 preguntas"], [/^(\d+) questions in this set$/, "$1 preguntas en este grupo"], [/^Route (\d)$/, "Ruta $1"]
];
function trText(s) {
  var k = s.trim(); if (!k) return null;
  if (ES_UI[k]) return s.replace(k, ES_UI[k]);
  for (var i = 0; i < ES_RX.length; i++) if (ES_RX[i][0].test(k)) { var r = k.replace(ES_RX[i][0], ES_RX[i][1]); if (r !== k) return s.replace(k, r); }
  return null;
}
function translateDom(root) {
  if (lang() !== "es" || !root) return;
  var w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: function (n) { var p = n.parentNode; return p && (p.closest("[data-notr],.logo,.brand,.legaltext,.esview,.qstem,.qopt,.explain,.dname,.dsub,.plain,.v,.phon,textarea,script,style") ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT); } }), n, out = [];
  while ((n = w.nextNode())) out.push(n);
  out.forEach(function (n) { var t = trText(n.nodeValue); if (t != null) n.nodeValue = t; });
  $$("[placeholder],[aria-label],[title]", root).forEach(function (el) { ["placeholder", "aria-label", "title"].forEach(function (a) { var v = el.getAttribute(a); if (v && ES_UI[v.trim()]) el.setAttribute(a, ES_UI[v.trim()]); }); });
}
function esView(id) {
  var e = DB.ES[id]; if (!e) return '';
  function R(k, v) { return v ? field(k, v) : ''; }
  return '<div class="esview" lang="es"><p class="esnote">Traducción preparada con IA; pendiente de revisión clínica. Ante cualquier duda, la versión en inglés es la referencia.</p>' +
    sec("Qué es", "", true, R("Nombre en español", e.name) + R("Qué hace", e.what)) +
    sec("Para qué se usa", "go", true, R("Usos", e.use)) +
    sec("No lo dé si", "stop", true, R("Contraindicaciones", e.dont)) +
    sec("Dosis", "dose", true, R("Dosis habitual en adultos", e.dose) + (scopeNote(id) ? R("Su nivel", scopeNote(id)) : "")) +
    sec("Qué vigilar", "", true, R("Vigilar", e.watch)) +
    sec("Para recordar", "", true, R("Dato clave", e.rem)) +
    sec("Educación al paciente", "", true, R("Qué decirle al paciente", e.edu)) + '</div>';
}
/* pronunciation: the "Say it" voice was removed (owner, Nov 16 2026: "remove the how to say it voice on the app. get rid
   of it completely"). The written pronunciation stays when Settings > show pronunciation is on. */
function sayBtn(id) { var e = DB.ES[id] || {}; return e.ph && SET().showPhon ? '<div class="sayrow"><span class="phon" data-notr>' + esc(e.ph) + '</span></div>' : ''; }
function i18nClick(t, a) {
  if (a.act === "lang") { setLang(lang() === "es" ? "en" : "es"); return true; }
  return false;
}
function esQNote() { return lang() === "es" ? '<p class="esnote">Las preguntas de práctica, los casos y las tarjetas están en inglés por ahora. Las páginas de cada medicamento tienen versión en español.</p>' : ''; }

/* ---------- Report an error: learners flag drug/question problems; the team works them in the Control Center ---------- */
// reports/<uid> : {items:[{id, ts, kind:"drug"|"question", ref, drug, type, text, email, ctx, status:"open"|"resolved", note}]}
var RP = { open: null, sent: null, err: "", list: null, filter: "open" };
var RTYPES = ["Wrong or unsafe dose", "Wrong fact or outdated info", "Answer marked wrong is actually right", "Confusing wording", "Typo or formatting", "Spanish translation problem", "Other"];
var rdlg = document.createElement("div"); rdlg.id = "rdlg"; rdlg.className = "sheet rsheet"; rdlg.hidden = true; document.body.appendChild(rdlg);
function reportBtn(kind, ref, drug) { return '<button class="linkish rptbtn" data-report="' + esc(kind + "|" + ref + "|" + (drug || "")) + '">' + (kind === "question" ? "Report a problem with this question" : "Report an error") + '</button>'; }
function qRef(q) { return typeof qid === "function" ? qid(q) : String(q.q || "").slice(0, 60); }
function openReport(spec) {
  var p = spec.split("|"), kind = p[0], ref = p[1], drug = p[2], q = null;
  if (kind === "question") q = DB.Q.concat(DB.QX || [], DB.RQ || []).filter(function (x) { return qRef(x) === ref; })[0];
  RP.open = { kind: kind, ref: ref, drug: drug || (q && q.d) || "", qtext: q ? q.q : "", type: kind === "question" ? RTYPES[2] : RTYPES[1], text: "", email: "" }; RP.sent = null; RP.err = "";
  drawReport(); rdlg.hidden = false; var f = $("#rptext", rdlg); if (f) f.focus();
}
function closeReport() { rdlg.hidden = true; rdlg.innerHTML = ""; RP.open = null; }
function reportMail(o) {
  var body = "Report type: " + o.type + "\nWhat: " + (o.kind === "question" ? "Question " + o.ref + "\n" + o.qtext : "Drug: " + nameOf(o.drug)) + "\nLevel: " + ctxKey() + "\n\nDetails:\n" + o.text + "\n";
  return "mailto:" + CONTACT + "?subject=" + encodeURIComponent("DrugBug error report: " + (o.drug ? nameOf(o.drug) : o.ref)) + "&body=" + encodeURIComponent(body);
}
function drawReport() {
  var o = RP.open; if (!o) return;
  var c = '<div class="panel" role="dialog" aria-modal="true" aria-label="Report an error" tabindex="-1"><div class="navrow"><h2 class="dname">Report an error</h2><span class="spacer"></span><button class="iconbtn" data-ract="close">Close</button></div>';
  c += '<p class="muted">' + (o.kind === "app" ? 'About: <strong>the DrugBug app</strong>' : o.kind === "question" ? 'Question: <em>' + esc(o.qtext.slice(0, 220)) + '</em>' : 'Drug: <strong>' + esc(nameOf(o.drug)) + '</strong>') + '</p>';
  if (RP.sent === "ok") return rdlg.innerHTML = c + '<div class="presult good" role="status">' + (!HASDB ? 'Your email app opened with the report filled in. Tap Send there to reach the DrugBug team.' : 'Thanks. Your report was sent to the DrugBug team for clinical review.') + '</div><div class="actions"><button class="btn" data-ract="close">Done</button></div></div>';
  c += '<div class="pform"><label>What is wrong?<select class="pinput" id="rptype">' + RTYPES.map(function (t) { return '<option' + (o.type === t ? " selected" : "") + '>' + esc(t) + '</option>'; }).join("") + '</select></label>';
  c += phiWarn() + '<label>Details (what it says, what it should say, and your source if you have one)<textarea class="pinput" id="rptext" rows="5" maxlength="1500">' + esc(o.text) + '</textarea></label>';
  c += '<label>Your email (optional, only if you want a reply)<input class="pinput" id="rpemail" type="email" maxlength="200" value="' + esc(o.email) + '"></label>' + phiWarn();
  if (RP.err) c += '<div class="presult" role="alert">' + esc(RP.err) + ' <a class="linkish" href="' + esc(reportMail(o)) + '" target="_blank" rel="noopener">Email the report instead</a></div>';
  c += '<div class="actions"><button class="btn" data-ract="send"' + (RP.busy ? " disabled" : "") + '>Send report</button><button class="btn ghost" data-ract="close">Cancel</button></div></div>';
  rdlg.innerHTML = c + '</div>';
}
function sendReport() {
  var o = RP.open; o.type = $("#rptype", rdlg).value; o.text = $("#rptext", rdlg).value.trim(); o.email = $("#rpemail", rdlg).value.trim();
  if (o.text.length < 5) { RP.err = "Add a few words about what is wrong."; return drawReport(); }
  var db = Prog.db || Dex.db, uid = Prog.uid;
  if (!HASDB) { window.location.href = reportMail(o); RP.sent = "ok"; return drawReport(); }
  if (!db || !uid) { RP.err = "Reports need an internet connection and a signed-in DrugBug account."; return drawReport(); }
  var item = { id: "r" + Date.now().toString(36), ts: Date.now(), kind: o.kind, ref: o.ref, drug: o.drug || "", qtext: (o.qtext || "").slice(0, 400), type: o.type, text: o.text.slice(0, 1500), email: o.email.slice(0, 200), ctx: ctxKey() || "", lang: lang(), status: "open" };
  RP.busy = true; drawReport();
  var ref = db.doc("reports/" + uid);
  ref.get().then(function (s) { var items = (s.exists && s.data().items) || []; items.push(item); return ref.set({ items: items.slice(-100) }); })
    .then(function () { RP.sent = "ok"; RP.err = ""; RP.list = null; }).catch(function () { RP.err = "Could not send the report right now."; })
    .then(function () { RP.busy = false; drawReport(); });
}
rdlg.addEventListener("click", function (e) {
  if (e.target === rdlg) return closeReport();
  var t = e.target.closest("[data-ract]"); if (!t) return;
  var act = t.getAttribute("data-ract"); if (act === "close") return closeReport(); if (act === "send") return sendReport();
});
rdlg.addEventListener("input", function (e) { if (!RP.open) return; if (e.target.id === "rptext") RP.open.text = e.target.value; if (e.target.id === "rpemail") RP.open.email = e.target.value; });
document.addEventListener("keydown", function (e) { if (e.key === "Escape" && RP.open) closeReport(); });

/* Control Center: error reports */
function loadReports(cb) {
  if (!Dex.db) { RP.list = []; return cb && cb(); }
  Dex.db.collection("reports").limit(500).get().then(function (qs) {
    var all = []; qs.docs.forEach(function (d) { ((d.data() || {}).items || []).forEach(function (r, i) { r.uid = d.id; all.push(r); }); });
    RP.list = all.sort(function (a, b) { return b.ts - a.ts; });
  }).catch(function () { RP.list = []; }).then(function () { cb && cb(); });
}
function reportsFor(id) { return !Array.isArray(RP.list) ? 0 : RP.list.filter(function (r) { return r.drug === id && r.status !== "resolved"; }).length; }
function reportsView() {
  if (!RP.list) { RP.list = "loading"; loadReports(render); }
  if (RP.list === "loading") return '<p class="muted">Loading reports…</p>';
  var f = RP.filter, L = RP.list.filter(function (r) { return f === "all" || (f === "open" ? r.status !== "resolved" : r.status === "resolved"); });
  var nopen = RP.list.filter(function (r) { return r.status !== "resolved"; }).length;
  var c = '<div class="chips subtabs">' + [["open", "Open (" + nopen + ")"], ["resolved", "Resolved"], ["all", "All"]].map(function (x) { return '<button class="chip" data-aact="rpf" data-rpf="' + x[0] + '" aria-pressed="' + (f === x[0]) + '">' + x[1] + '</button>'; }).join("") + '<button class="chip" data-aact="rpreload">Refresh</button></div>';
  c += '<p class="muted small">Reports from learners. Fix the drug or question, then mark the report resolved. Drugs with open reports are flagged in the Review queue.</p>';
  if (!L.length) return c + '<p class="muted">No reports here.</p>';
  return c + '<div class="alist">' + L.slice(0, 200).map(function (r) {
    return '<div class="arow rprow"><div><strong>' + esc(r.type) + '</strong> · ' + (r.drug ? '<button class="linkish" data-aedit="' + esc(r.drug) + '">' + esc(nameOf(r.drug)) + '</button>' : '') + (r.kind === "question" ? ' <span class="muted small">Question: ' + esc(String(r.qtext || r.ref || "").slice(0, 160)) + '</span>' + (r.ref ? ' <button class="linkish" data-aqedit="' + esc(r.ref) + '">Open question</button>' : '') : '') +
      '<p>' + esc(r.text) + '</p><span class="muted small">' + esc(fmtDate(r.ts)) + ' · ' + esc(r.ctx || "") + (r.lang === "es" ? ' · Spanish' : '') + (r.email ? ' · ' + esc(r.email) : '') + '</span></div>' +
      (r.status === "resolved" ? pill("Resolved", "on") + '<button class="btn small ghost" data-aact="rpreopen" data-rpid="' + esc(r.uid + "|" + r.id) + '">Reopen</button>' : '<button class="btn small" data-aact="rpresolve" data-rpid="' + esc(r.uid + "|" + r.id) + '">Mark resolved</button>') + '</div>';
  }).join("") + '</div>';
}
function setReportStatus(spec, status) {
  var p = spec.split("|"), ref = Dex.db.doc("reports/" + p[0]);
  Admin.busy = true;
  ref.get().then(function (s) {
    var items = (s.exists && s.data().items) || []; items.forEach(function (r) { if (r.id === p[1]) { r.status = status; r.resolvedTs = Date.now(); r.resolvedBy = Admin.uid || ""; } });
    return ref.set({ items: items });
  }).then(function () { (RP.list || []).forEach(function (r) { if (r.uid === p[0] && r.id === p[1]) r.status = status; }); Admin.msg = status === "resolved" ? "Report marked resolved." : "Report reopened."; })
    .catch(function (e) { Admin.msg = "Could not update (" + (e && e.code || "error") + ")."; }).then(function () { Admin.busy = false; render(); });
}

/* ---------- Printables: drug cards and shift cheat sheets (print, or download as HTML) ---------- */
var printv = document.createElement("div"); printv.id = "printv"; printv.hidden = true; document.body.appendChild(printv);
var PR = null;
function canPrint() { return !NATIVE || !!(window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.print); }
function printBtns(src, label) {
  if (!canPrint()) return "";
  /* every layout is offered here; the detail level is then changed in the print view itself */
  return '<details class="printmenu"><summary class="btn small ghost">Print</summary><div class="pmlist">' +
    PR_LAYOUTS.map(function (L) { return '<button class="btn small ghost" data-print="' + esc(src) + '|' + L[0] + '">' + esc(L[1]) + '</button>'; }).join("") +
    (label ? '<span class="muted small">' + esc(label) + '</span>' : '') + '</div></details>';
}
function printIds(src) { return printIds0(src).filter(function (id) { return !(typeof drugLocked === "function" && drugLocked(id)); }); }
function printIds0(src) {
  if (src === "marks") return marks().filter(function (id) { return DB.drugs[id]; });
  if (src === "filter") return filteredIds().filter(function (id) { return DB.drugs[id]; });
  if (src.indexOf("drug:") === 0) return [src.slice(5)];
  if (src.indexOf("ids:") === 0) return src.slice(4).split(",").filter(function (id) { return DB.drugs[id]; });
  return [];
}
function openPrint(spec) {
  var p = spec.split("|"), ids = printIds(p[0]);
  var sp = SET(); PR = { src: p[0], ids: ids.slice(0, 200), mode: p[1] || sp.printMode, detail: p[2] || sp.printDetail || "std", es: false, dense: sp.printDense, msg: "" };
  if (sheet && !sheet.hidden) closeSheet();
  drawPrint(); printv.hidden = false; document.body.classList.add("printing"); window.scrollTo(0, 0);
}
function closePrint() { printv.hidden = true; printv.innerHTML = ""; PR = null; document.body.classList.remove("printing"); }
function pf(id, si, fi) { var d = DB.drugs[id]; return d ? get(d, si, fi) : ""; }
/* ---------- print layouts and how much detail goes on them (owner, Nov 4 2026) ----------
   PR.mode picks the page design, PR.detail picks how much of each drug goes on it. The two are
   independent, so a pocket card can be brief and a monograph can be exhaustive. */
var PR_LAYOUTS = [
  ["cards",  "Study cards",   "Two to a row, boxed. The classic."],
  ["sheet",  "Cheat sheet",   "One table, one row per drug."],
  ["pocket", "Pocket card",   "Three narrow columns to fold and carry."],
  ["mono",   "Monograph",     "One drug per page, everything you have."],
  ["quiz",   "Quiz sheet",    "Prompts with blank lines, answer key at the back."],
  ["flash",  "Cut-out flashcards", "Front and back pairs with cut lines."]
];
var PR_DETAIL = [
  ["brief", "Brief",    "Class and dose only."],
  ["std",   "Standard", "The working facts."],
  ["full",  "Full",     "Everything, including mechanism and interactions."]
];
/* [label, section, field, max characters]. Each level adds to the one before it. */
var PR_FIELDS = {
  brief: [["Class", 0, 3, 60], ["Adult dose", 6, 0, 220]],
  std: [["Class", 0, 3, 60], ["What it does", 1, 1, 260], ["Used for", 3, 0, 260],
        ["Contraindications", 4, 0, 260], ["Adult dose", 6, 0, 240], ["Pediatric dose", 6, 1, 180],
        ["Routes", 7, 0, 90], ["Watch for", 9, 1, 240], ["Key fact", 16, 3, 200]],
  full: [["Class", 0, 3, 60], ["Pharmacologic class", 0, 4, 80], ["What it is", 1, 0, 300],
         ["What it does", 1, 1, 320], ["Mechanism", 2, 0, 420], ["Used for", 3, 0, 320],
         ["EMS indications", 3, 2, 260], ["Absolute contraindications", 4, 0, 320],
         ["Relative contraindications", 4, 1, 240], ["Boxed warning", 5, 1, 260],
         ["Adult dose", 6, 0, 320], ["Pediatric dose", 6, 1, 240], ["Max dose", 6, 3, 160],
         ["Routes", 7, 0, 120], ["Onset", 8, 0, 90], ["Duration", 8, 2, 90],
         ["Common side effects", 9, 0, 280], ["Serious side effects", 9, 1, 300],
         ["Major interactions", 10, 0, 320], ["Monitor", 11, 8, 220],
         ["Antidote", 13, 4, 160], ["Clinical pearl", 14, 7, 280], ["Key fact", 16, 3, 220]]
};
function prDetail() { return (PR && PR.detail) || "std"; }
function prTitle() { return "DrugBug " + ((PR_LAYOUTS.filter(function (L) { return L[0] === PR.mode; })[0] || PR_LAYOUTS[0])[1]).toLowerCase(); }
function prRows(id) {
  var es = PR.es && DB.ES[id];
  if (es) {
    var L = [["Qué es", es.what], ["Usos", es.use], ["No lo dé si", es.dont], ["Dosis (adulto)", es.dose], ["Vigilar", es.watch], ["Dato clave", es.rem]];
    if (prDetail() === "brief") L = L.slice(3, 4);
    return L.filter(function (r) { return r[1]; }).map(function (r) { return [r[0], cut(r[1], 260)]; });
  }
  return (PR_FIELDS[prDetail()] || PR_FIELDS.std).map(function (f) {
    var v = pf(id, f[1], f[2]);
    if (f[0] === "What it does" && !v) v = pf(id, 2, 0);
    if (f[0] === "Watch for" && !v) v = pf(id, 9, 0);
    if (f[0] === "Key fact" && !v) v = pf(id, 16, 4);
    return v && v !== "-" ? [f[0], cut(v, f[3])] : null;
  }).filter(Boolean);
}
function cut(s, n) { s = String(s || ""); return s.length > n ? s.slice(0, n - 1).replace(/\s+\S*$/, "") + "…" : s; }
function cardHtml(id) {
  var d = DB.drugs[id], note = scopeNote(id);
  function r(k, v) { return v ? '<div class="pr-r"><b>' + esc(k) + '</b> ' + esc(v) + '</div>' : ''; }
  var h = '<article class="pr-card"><header><h3>' + esc(d.name) + '</h3><span>' + esc(cut(pf(id, 0, 3), 60)) + '</span></header>' + (DB.ES[id] ? '<div class="pr-ph">' + esc(DB.ES[id].ph) + '</div>' : '');
  h += prRows(id).map(function (x) { return r(x[0], x[1]); }).join("");
  if (note) h += r(PR.es ? "Su nivel" : "Your scope", cut(note, 160));
  return h + prFoot(id) + '</article>';
}
/* the source line and the study-card disclaimer, shared by every layout */
function prFoot(id) {
  var L = typeof labelSrc === "function" ? labelSrc(id) : null;
  return '<div class="pr-src">' + (L ? (PR.es ? "Fuente de dosis: etiqueta de la FDA" : "Dose source: FDA label") + ' (' + esc([L.b, L.m].filter(Boolean).join(", ")) + (L.d ? ", " + esc(L.d) : "") + ')' : (PR.es ? "Verifique la dosis con la etiqueta actual de la FDA." : "Verify any dose with the current FDA label.")) + '</div>' +
    '<div class="pr-tag">' + (PR.es ? "Tarjeta de estudio: verifique con su protocolo y la etiqueta de la FDA. No es para atención de pacientes." : "Study card - verify with your protocol and the FDA label. Not for patient care.") + '</div>';
}

function sheetHtml(ids) {
  var es = PR.es, det = prDetail();
  /* the columns follow the detail level: brief is two, full adds mechanism and interactions */
  var cols = det === "brief" ? [["Medicamento", "Drug", null], ["Clase", "Class", [0, 3, 60]], ["Dosis (adulto)", "Adult dose", [6, 0, 200]]]
    : det === "full" ? [["Medicamento", "Drug", null], ["Clase", "Class", [0, 3, 50]], ["Mecanismo", "Mechanism", [2, 0, 190]], ["Dosis (adulto)", "Adult dose", [6, 0, 150]], ["Contraindicaciones", "Contraindications", [4, 0, 120]], ["Interacciones", "Interactions", [10, 0, 130]], ["Vigilar", "Watch for", [9, 1, 110]]]
    : [["Medicamento", "Drug", null], ["Clase", "Class", [0, 3, 50]], ["Dosis (adulto)", "Adult dose", [6, 0, 170]], ["Contraindicaciones", "Contraindications", [4, 0, 120]], ["Vigilar", "Watch for", [9, 1, 120]]];
  return '<table class="pr-table' + (det === "full" ? ' pr-wide' : '') + '"><thead><tr>' + cols.map(function (c) { return '<th>' + esc(es ? c[0] : c[1]) + '</th>'; }).join("") + '</tr></thead><tbody>' + ids.map(function (id) {
    var e = es && DB.ES[id];
    return '<tr>' + cols.map(function (c) {
      if (!c[2]) return '<td><b>' + esc(DB.drugs[id].name) + '</b></td>';
      var v = pf(id, c[2][0], c[2][1]);
      if (e) { if (c[1] === "Adult dose") v = e.dose; else if (c[1] === "Contraindications") v = e.dont; else if (c[1] === "Watch for") v = e.watch; }
      if (c[1] === "Watch for" && !v) v = pf(id, 9, 0);
      return '<td>' + esc(cut(v, c[2][2])) + '</td>';
    }).join("") + '</tr>';
  }).join("") + '</tbody></table>';
}

/* pocket card: three narrow columns, one compact entry each, meant to be folded */
function pocketHtml(ids) {
  return '<div class="pr-pocket">' + ids.map(function (id) {
    var rows = prRows(id);
    return '<div class="pp-item"><b>' + esc(DB.drugs[id].name) + '</b>' +
      rows.map(function (x) { return '<span class="pp-r"><i>' + esc(x[0]) + '</i> ' + esc(cut(x[1], prDetail() === "full" ? 200 : 110)) + '</span>'; }).join("") +
      '</div>';
  }).join("") + '</div>';
}
/* monograph: one drug per page, with every row the detail level allows */
function monoHtml(ids) {
  return ids.map(function (id, i) {
    var d = DB.drugs[id], note = scopeNote(id);
    return '<section class="pr-mono' + (i ? ' pr-break' : '') + '"><h2>' + esc(d.name) + '</h2>' +
      '<p class="pr-msub">' + esc(cut(pf(id, 0, 3), 90)) + (pf(id, 0, 1) ? ' \u00b7 ' + esc(cut(pf(id, 0, 1), 80)) : '') + '</p>' +
      (DB.ES[id] ? '<div class="pr-ph">' + esc(DB.ES[id].ph) + '</div>' : '') +
      '<dl class="pr-dl">' + prRows(id).map(function (x) { return '<dt>' + esc(x[0]) + '</dt><dd>' + esc(x[1]) + '</dd>'; }).join("") +
      (note ? '<dt>' + (PR.es ? "Su nivel" : "Your scope") + '</dt><dd>' + esc(note) + '</dd>' : '') + '</dl>' + prFoot(id) + '</section>';
  }).join("");
}
/* quiz sheet: the prompt and ruled blank lines, then an answer key on its own page */
function quizHtml(ids) {
  var keys = prDetail() === "brief" ? ["Class", "Adult dose"]
    : prDetail() === "full" ? ["Class", "Mechanism", "Used for", "Absolute contraindications", "Adult dose", "Pediatric dose", "Serious side effects", "Major interactions"]
    : ["Class", "What it does", "Used for", "Contraindications", "Adult dose", "Watch for"];
  var q = '<div class="pr-quiz">' + ids.map(function (id, i) {
    return '<div class="pq-item"><h3>' + (i + 1) + '. ' + esc(DB.drugs[id].name) + '</h3>' +
      keys.map(function (k) { return '<div class="pq-r"><b>' + esc(k) + '</b><span class="pq-line"></span></div>'; }).join("") + '</div>';
  }).join("") + '</div>';
  var ans = '<section class="pr-break pr-key"><h2>' + (PR.es ? "Clave de respuestas" : "Answer key") + '</h2>' + ids.map(function (id, i) {
    var byK = {}; prRows(id).forEach(function (x) { byK[x[0]] = x[1]; });
    return '<div class="pk-item"><b>' + (i + 1) + '. ' + esc(DB.drugs[id].name) + '</b>' +
      keys.map(function (k) { return byK[k] ? '<span class="pk-r"><i>' + esc(k) + '</i> ' + esc(byK[k]) + '</span>' : ''; }).join("") + '</div>';
  }).join("") + '</section>';
  return q + ans;
}
/* cut-out flashcards: a front and a back for each drug, with cut lines */
function flashHtml(ids) {
  return '<div class="pr-flash">' + ids.map(function (id) {
    var rows = prRows(id);
    return '<div class="pf-card pf-front"><span class="pf-lbl">' + (PR.es ? "frente" : "front") + '</span><strong>' + esc(DB.drugs[id].name) + '</strong>' + (DB.ES[id] ? '<em>' + esc(DB.ES[id].ph) + '</em>' : '') + '</div>' +
      '<div class="pf-card pf-back"><span class="pf-lbl">' + (PR.es ? "dorso" : "back") + '</span>' +
      rows.map(function (x) { return '<span class="pf-r"><i>' + esc(x[0]) + '</i> ' + esc(cut(x[1], prDetail() === "full" ? 240 : 150)) + '</span>'; }).join("") + '</div>';
  }).join("") + '</div>';
}
function printDoc() {
  var ids = PR.ids, dt = fmtDate(Date.now()), es = PR.es;
  var LT = { cards: [ "Tarjetas de estudio", "Study cards" ], sheet: [ "Hoja de referencia rápida", "Shift cheat sheet" ],
             pocket: [ "Tarjeta de bolsillo", "Pocket card" ], mono: [ "Monografías", "Monographs" ],
             quiz: [ "Hoja de examen", "Quiz sheet" ], flash: [ "Tarjetas para cortar", "Cut-out flashcards" ] };
  var title = (LT[PR.mode] || LT.cards)[es ? 0 : 1];
  var foot = '<p class="pr-foot">DrugBug · ' + (es ? "Solo para uso educativo; no es para tomar decisiones clínicas. Verifique con referencias actuales y sus protocolos locales." : "Educational use only — not for clinical decision-making. Verify with current references and your local protocols.") + ' Printed ' + esc(dt) + '. © ' + COMPANY + '.</p>';
  var D = (PR_DETAIL.filter(function (x) { return x[0] === prDetail(); })[0] || PR_DETAIL[1])[1];
  var body = PR.mode === "sheet" ? sheetHtml(ids)
    : PR.mode === "pocket" ? pocketHtml(ids)
    : PR.mode === "mono" ? monoHtml(ids)
    : PR.mode === "quiz" ? quizHtml(ids)
    : PR.mode === "flash" ? flashHtml(ids)
    : '<div class="pr-cards' + (PR.dense ? ' pr-dense' : '') + '">' + ids.map(cardHtml).join("") + '</div>';
  return '<div class="pr-doc"><h1 class="pr-title">' + title + ' <small>' + ids.length + (es ? (ids.length === 1 ? " medicamento" : " medicamentos") : (ids.length === 1 ? " drug" : " drugs")) + ' \u00b7 ' + esc(D.toLowerCase()) + '</small></h1>' + body + foot + '</div>';
}
