function exportData() {
  var data = { app: "DrugBug", version: APP_VERSION, exported: new Date().toISOString(), progress: Prog.d, scores: Scores.items, settings: SET(), theme: themePref(), language: lang(), protocol: store("protocol") || null, agreement: agreeRec() };
  var name = "drugbug-my-data-" + new Date().toISOString().slice(0, 10) + ".json";
  var sh = window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.share;
  if (sh) { try { sh.postMessage({ name: name, data: JSON.stringify(data, null, 2) }); S.setMsg = "Choose where to save or send your data file."; } catch (e) { S.setMsg = "Could not export right now."; } return render(); }
  if (!window.claude || typeof window.claude.use !== "function") { S.setMsg = "Downloads are not available here."; return render(); }
  window.claude.use("downloads").then(function (dl) {
    if (!dl) { S.setMsg = "Downloads are not available here."; return render(); }
    return dl.save({ filename: name, data: JSON.stringify(data, null, 2) }).then(function () { S.setMsg = "Saved " + name + "."; render(); }, function (e) { S.setMsg = e && e.code === "declined" ? "Download cancelled." : "Could not download right now."; render(); });
  }).catch(function () { S.setMsg = "Could not download right now."; render(); });
}
function setNum(k, v) { return ["dailyGoal", "nrN"].indexOf(k) >= 0 ? +v : ["adaptive", "fullDefault", "printDense"].indexOf(k) >= 0 ? v === "1" : v; }
function settingsClick(t, a) {
  if (a.set) {
    var k = a.set, v = a.val;
    if (k === "theme") { store("theme", v); applySettings(); }
    else if (k === "lang") { store("lang", v); if (typeof LANG_C !== "undefined") LANG_C = null; }
    else setSet(k, setNum(k, v));
    if (k === "nrN" || k === "nrMode" || k === "adaptive") S.nr = null;
    render(); var f = $('[data-set="' + k + '"][data-val="' + v + '"]'); if (f) f.focus(); return true;
  }
  if (a.settab) { S.setTab = a.settab; render(); var tb = $('[data-settab="' + a.settab + '"]'); if (tb) tb.focus(); return true; }
  if (a.setjump) { var el = document.getElementById("set-" + a.setjump); if (el) el.scrollIntoView({ behavior: SET().motion ? "auto" : "smooth", block: "start" }); return true; }
  switch (a.act) {
    case "music": MU.armed = true; S.mupop = !S.mupop;
      /* the box floats just under the button, wherever the page is scrolled to. It used to sit in
         the page flow at the top, so when scrolled down it opened out of sight and nudged the page
         (owner, Nov 5 2026) */
      try { var mb = t.closest ? t.closest(".musicbtn") : null; mb = mb || document.querySelector(".musicbtn"); if (mb) { var rr = mb.getBoundingClientRect(); document.documentElement.style.setProperty("--mupopTop", Math.round(rr.bottom + 8) + "px"); } } catch (e) {}
      render(); return true;
    case "mutoggle": MU.armed = true; setSet("music", !muOn()); render(); return true;
    case "mupopclose": S.mupop = false; render(); return true;
    case "munext": MU.armed = true; if (!muOn()) setSet("music", true); muNext(); if (!MU.playing) muSync(); return true;
    case "sfxtest": var was = SET().sfx; if (!was) setSet("sfx", true); sfx(true); setTimeout(function () { sfx(false); if (!was) setSet("sfx", false); render(); }, 450); return true;
    case "sndrecheck":
      audioCtx(); AUD.played = Math.max(0, AUD.played - 1);     /* the check itself should not count */
      try { if (muCtx() && typeof muLoadBuf === "function" && typeof curTrack === "function") muLoadBuf(curTrack()); } catch (e) { AUD.music = "fail"; }
      try { sfxLoad("gasp"); } catch (e) {}
      setTimeout(render, 700); return true;
    case "exportdata": exportData(); return true;
    case "resetask": S.resetAsk = true; render(); return true;
    case "resetno": S.resetAsk = false; render(); return true;
    case "resetyes": resetProgress(); return true;
    case "fmhide": try { localStorage.removeItem("drugbug:fmUnlock"); } catch (x) {} store("fmUnlock", null); S.setMsg = "Combat Paramedic & Prolonged Care is hidden again. Redeem the code to bring it back."; render(); return true;
  }
  return false;
}
document.addEventListener("change", function (e) {
  var t = e.target; if (!t.getAttribute) return;
  var k = t.getAttribute("data-settog");
  if (k === "adMeas") { store("adMeasOff", !t.checked); adMeasSync(); render(); var f1 = $('[data-settog="adMeas"]'); if (f1) f1.focus(); return; }
  if (k === "statsOpt") { statsSet(t.checked, "settings"); render(); var f0 = $('[data-settog="statsOpt"]'); if (f0) f0.focus(); return; }
  if (k) { setSet(k, t.checked); render(); var f = $('[data-settog="' + k + '"]'); if (f) f.focus(); return; }
  k = t.getAttribute("data-setsel");
  if (k === "protocol") { store("protocol", t.value || null); DB._ncache = {}; DB._mcache = null; S.setMsg = t.value ? "Protocols updated. Your levels now follow them." : "Using national defaults."; render(); return; }
  if (k) { setSet(k, t.value); if (k === "state") P.state = t.value; if (k === "holPreview") { var hs = SET(); hs.holPreviewTs = Date.now(); store("settings", hs); } render(); }
});
document.addEventListener("submit", function (e) {
  var f = e.target; if (!f.getAttribute) return;
  if (f.getAttribute("data-fmcode")) { e.preventDefault(); if (NATIVE) return; fmCodeTry((($("#fmcodein") || {}).value || "")); return; }
  if (f.getAttribute("data-setlb")) {
    e.preventDefault(); var nm = (($("#setlbname") || {}).value || "").trim(); if (!nm || isMinor()) return;
    if (!nameOk(nm)) { S.setMsg = ""; S.lbMsg = NAMEMSG; alertMsg(NAMEMSG); return; }
    Prog.d.lbName = nm.slice(0, 40); CL.lbTs = 0; CL.lb = null; saveProg(); lbPush(); S.setMsg = "Leaderboard name saved."; render();
  }
  if (f.getAttribute("data-setcl")) {
    e.preventDefault(); var cn = (($("#setclname") || {}).value || "").trim(); if (!cn || !CL.roster) return;
    if (!nameOk(cn)) { alertMsg(NAMEMSG); return; }
    CL.roster.name = cn.slice(0, 60); saveRoster().then(function () { S.setMsg = "Class name saved."; }).catch(function () { S.setMsg = "Could not save the class name."; }).then(render);
  }
});
function alertMsg(m) { S.setMsg = m; render(); var el = $(".settings .presult"); if (el) { el.classList.remove("good"); el.setAttribute("role", "alert"); } }
applySettings();
