  var chain = Promise.resolve();
  PQ.photos.forEach(function (p, i) { chain = chain.then(function () { return P.db.doc("protoFiles/" + P.uid + "/photos/" + pids[i]).set({ reqId: rid, n: i + 1, name: p.name || "", data: p.data, w: p.w, h: p.h, ts: Date.now() }); }); });
