    var all = []; qs.docs.forEach(function (d) { var x = d.data(); (x && x.items || []).forEach(function (r, i) { r.uid = d.id; r.idx = i; all.push(r); }); });
    P.inbox = all.sort(function (a, b) { return b.ts - a.ts; });
