    Promise.all((r.photos || []).map(function (pid) { return db.doc("protoFiles/" + r.uid + "/photos/" + pid).get().then(function (s) { return s.exists ? s.data() : null; }, function () { return null; }); }))
      .then(function (ps) { PQ.seen[key] = ps; pqRedraw(); });
