function hasBlood() { return S.view === "level" && (S.level === "flight" || S.level === "cmc" || S.level === "cpp" || S.level === "pcc" || flightRN()); }
function hasHemo() { return S.view === "level" && (S.level === "flight" || isM(S.level) || flightRN() || (S.level === "rn" && typeof myUnit === "function" && myUnit("rn") === "icu")); }
function critData(kind) { return kind === "flightp" ? DB.FLIGHTP : kind === "blood" ? DB.BLOOD : kind === "contrast" ? DB.CONTRAST : DB.HEMO; }
function critKey(kind) { return kind === "flightp" ? "fl" : kind === "contrast" ? S.level : S.level === "rn" ? "fl" : labRoute(); }
function critTopics(kind) { var r = critKey(kind), d = critData(kind); return d ? d.topics.filter(function (t) { return !t.lv || t.lv.indexOf(r) >= 0; }) : []; }
function critQs(kind) { var r = critKey(kind), d = critData(kind); return d ? d.q.filter(function (q) { return !q.lv || q.lv === r; }) : []; }
var CRIT_GDESC = {
  "Products": "What each product is and when to give it.", "Compatibility": "ABO, Rh and the checks before you hang it.", "Giving blood in transport": "Filters, warmers, coolers and rates.",
  "Hemorrhage resuscitation": "MTP, ratios, TXA, calcium and reversal.", "Transfusion reactions": "Spot it, stop it, treat it.", "Special situations": "OB, GI bleeds, kids and refusals.",
  "Foundations": "Preload, afterload, normals and formulas.", "Monitoring lines": "A-line, CVP, PA catheter, wedge and SvO2.", "Shock": "Profiles, SCAI stages, RV failure and pressors.",
  "Mechanical circulatory support": "IABP, Impella, ECMO, LVAD and pacing.", "Interventional cardiology": "Cath lab, PCI and valve hemodynamics.", "Gas laws": "Boyle, Dalton, Charles, Henry and the rest at altitude.", "Stresses of flight": "Hypoxia, TUC, trapped gas and decompression illness.", "Critical care challenge": "Hard FP-C and CFRN style scenarios."
};
function critBox(kind, id) { var B = kind === "flightp" ? DB.FLIGHTPBOX : kind === "blood" ? DB.BLOODBOX : kind === "hemo" ? DB.HEMOBOX : kind === "contrast" ? DB.CONTRASTBOX : null; return B && B[id] || null; }
function ctm(kind, id) { var M = Prog.d.ctm || (Prog.d.ctm = {}); return M[kind + ":" + id] || (M[kind + ":" + id] = { r: 0, n: 0, s: 0 }); }
function ctLevel(kind, id) { var m = (Prog.d.ctm || {})[kind + ":" + id]; if (!m || !m.n) return "new"; if (m.s >= 3) return "mastered"; if (m.s >= 1 || m.r / m.n >= .6) return "familiar"; return "learning"; }
