  var t = e.target.closest("[data-wdw]"); if (!t) { if (e.target === wdwdlg) wdwClose(); return; }
  var a = t.getAttribute("data-wdw");
  if (a === "close") return wdwClose();
  if (a === "drug") { var id = t.getAttribute("data-id"); wdwClose(); if (DB.drugs[id]) openSheet(id); return; }
