  if (!GM.shown) c += '<div class="scrtiles">' + GM.tiles.map(function (ch, k) { var used = GM.pick.indexOf(k) >= 0; return '<button class="tile' + (used ? " used" : "") + '" data-gmtile="' + k + '"' + (used ? " disabled" : "") + '>' + ch + '</button>'; }).join("") + '</div>' +
    '<div class="actions"><button class="btn ghost small" data-gm="scrback"' + (GM.pick.length ? "" : " disabled") + '>Undo</button><button class="btn ghost small" data-gm="scrskip">Show answer</button></div>';
  else c += '<div class="explain ' + (typed === w.w ? "ok" : "bad") + '"><strong>' + (typed === w.w ? "Correct: " : "The answer: ") + esc(nameOf((gmIds().filter(function (id) { return DB.drugs[id].name.toUpperCase() === w.w; })[0]) || w.w)) + '</strong>' + (typed === w.w ? ' <span class="earned">+1 stick</span>' : '') + '</div><div class="actions"><button class="btn" data-gm="scrnext">' + (GM.i + 1 < GM.words.length ? "Next word" : "See results") + '</button></div>';
