var GFX_FLY = '<svg viewBox="0 0 120 50" width="110" height="46"><ellipse class="wl" cx="40" cy="14" rx="26" ry="7" fill="#a5f3fc" opacity=".8" transform="rotate(-12 40 14)"/><ellipse class="wr" cx="40" cy="34" rx="26" ry="7" fill="#a5f3fc" opacity=".8" transform="rotate(12 40 34)"/><ellipse class="wl" cx="62" cy="14" rx="22" ry="6" fill="#c4b5fd" opacity=".75" transform="rotate(12 62 14)"/><ellipse class="wr" cx="62" cy="34" rx="22" ry="6" fill="#c4b5fd" opacity=".75" transform="rotate(-12 62 34)"/><rect x="4" y="21" width="62" height="7" rx="3.5" fill="#0ea5e9"/><circle cx="82" cy="24" r="10" fill="#0284c7"/><circle cx="86" cy="20" r="4" fill="#fff"/><circle cx="87" cy="20" r="2" fill="#111"/></svg>';
