  /* 4 journey + PK */
  var pkf = [["Onset", 0], ["Peak", 1], ["Duration", 2], ["Half-life", 3], ["Metabolism", 4], ["Elimination", 5], ["Protein binding", 6]].map(function (x) { return [x[0], get(d, 8, x[1])]; }).filter(function (x) { return deepOk(x[1]); });
  var jr = (e ? deepP(e.journey) : '') + (pkf.length ? '<div class="pk">' + pkf.map(function (x) { return '<div><span>' + x[0] + '</span>' + esc(x[1]) + '</div>'; }).join("") + '</div>' : '');
  c += deepSec("🧭", "Its journey through the body", jr);
  /* 5 side effects */
  var sx = e ? deepP(e.sidefx) : '';
  var sl = [["Common", get(d, 9, 0)], ["Serious", get(d, 9, 1)], ["Life-threatening", get(d, 9, 2)]].filter(function (x) { return deepOk(x[1]); });
  if (sl.length) sx += '<div class="pk">' + sl.map(function (x) { return '<div><span>' + x[0] + '</span>' + esc(x[1]) + '</div>'; }).join("") + '</div>';
