  if (mem.length) c += deepSec("🧠", "Make it stick", '<div class="mem">' + mem.map(function (x) { return '<div><b>' + x[0] + ':</b> ' + esc(x[1]) + '</div>'; }).join("") + '</div>');
  if (typeof qaSection === "function") c += qaSection(id);
