  if (e.mem && e.mem.length) c += deepSec("🧠", "Make it stick", '<div class="mem">' + e.mem.map(function (m) { return '<div><b>' + esc(m[0]) + ':</b> ' + esc(m[1]) + '</div>'; }).join("") + '</div>');
  if (e.fun) c += '<div class="fun"><b>Fun fact:</b> ' + esc(e.fun) + '</div>';
