  var c = '<div class="deep trdetail"><div class="backrow"><button class="backbtn" data-trback="1"><span aria-hidden="true">&larr;</span> ' + (ic ? "All injuries &amp; illnesses" : "All trauma") + '</button></div>';
  c += '<header class="dishead"><span class="dsys">' + esc(FM_TR_GROUPS[T.g] || "") + '</span><h2>' + esc(T.name) + '</h2></header>' + deepP(T.what);
