  if (sel >= 0) c = c.replace('</header>', '</header><div class="icsel"><span>Variation</span><b>' + esc(ty[sel][0]) + '</b><p>' + esc(ty[sel][1]) + '</p></div>');
  if (ty.length) c += deepSec("🧩", "Types and patterns (" + ty.length + ")", '<div class="organs distypes">' + ty.map(function (t, i) { return '<div class="organ' + (i === sel ? ' icon' : '') + '"><b>' + esc(t[0]) + '</b>' + esc(t[1]) + '</div>'; }).join("") + '</div>');
  c += deepSec("👁️", "How it is recognized", li(T.signs.concat(M.signs2 || [])));
  if (M.mimic && M.mimic.length) c += deepSec("🔀", "What it can be mistaken for", '<div class="organs">' + M.mimic.map(function (t) { return '<div class="organ"><b>' + esc(t[0]) + '</b>' + esc(t[1]) + '</div>'; }).join("") + '</div>');
