/* ---- more field condition cards (owner, Oct 28 2026: "add the ones you can think of") ---- */
FM_TRAUMA.push(
  { id: "amp", g: 0, name: "Traumatic amputation", line: "A limb lost to blast or crush",
    what: "Partial or complete loss of a limb, most often from blast.",
    why: "Torn arteries can bleed out in minutes, though crushed vessels sometimes spasm shut at first. Blast amputations often come with pelvic, genital and other injuries.",
    signs: ["Missing or mangled limb", "Heavy bleeding, or a deceptively dry stump", "Shock", "Associated pelvic and perineal wounds"],
    care: [["asm", "Limb tourniquet high on the stump, with a second tourniquet if bleeding continues."], ["cls", "Tourniquets on amputations are not converted to dressings (TCCC conversion criteria exclude amputation)."], ["cmc", "Pelvic binder: TCCC lists any major lower limb amputation or near amputation as an indication after severe blunt force or blast."], ["cmc", "TXA, blood products and calcium; stump dressing; antibiotics for the open wound."], ["cpp", "Pain control, potassium and lactate trends, and early surgical evacuation."]],
    drugs: ["tranexamic-acid", "calcium-chloride", "ketamine", "ceftriaxone"],
    warn: ["A stump that is not bleeding at first can bleed later as vessels relax and blood pressure returns.", "Double amputations and pelvic injuries often travel together; the binder and the tourniquets are both checked."] },
  { id: "crush", g: 0, name: "Crush syndrome", line: "When freeing the limb releases the danger",
    what: "Muscle injury from prolonged compression, such as a casualty pinned under rubble or a vehicle.",
    why: "When the weight is lifted, potassium, acid and myoglobin from dead muscle flood the circulation, threatening the heart and kidneys within minutes to hours.",
    signs: ["Limb trapped for a long time (often over an hour)", "Swollen, tense, numb limb after release", "Dark, tea-colored urine", "Peaked T waves or arrhythmias", "Shock after extrication"],
    care: [["asm", "Rapid extrication and evacuation request."], ["cmc", "IV or IO fluid, ideally started before the limb is freed, to protect the kidneys."], ["cpp", "Cardiac monitoring; i-STAT potassium; high potassium is treated with calcium (heart protection), insulin with glucose and inhaled albuterol (shifting) and bicarbonate for severe acidosis; urine output tracked."]],
    drugs: ["calcium-chloride", "calcium-gluconate", "regular-insulin", "dextrose", "albuterol", "sodium-bicarbonate"],
    warn: ["A casualty who looks stable while trapped can arrest within minutes of release.", "Succinylcholine is avoided after the first day in crush injury because of potassium release."] },
  { id: "eye", g: 0, name: "Penetrating eye injury", line: "Shield it, do not press it",
    what: "A wound that penetrates the eye, often from fragments.",
    why: "Pressure on an open globe can push eye contents out, and infection inside the eye can destroy sight.",
    signs: ["Blast or fragment exposure to the face", "Teardrop-shaped pupil", "Visible wound or fluid from the eye", "Loss of vision"],
    care: [["asm", "Rigid eye shield over the eye; no pressure patch."], ["cls", "Rapid field visual acuity check, recorded on the DD1380."], ["cls", "Antibiotics as soon as possible: cefadroxil by mouth, or ceftriaxone when the casualty cannot swallow."], ["cpp", "Nausea control to prevent straining; evacuation to eye surgery."]],
    drugs: ["cefadroxil", "ceftriaxone", "ondansetron", "ketamine"],
    warn: ["Eye injury does not rule out ketamine (TCCC).", "Both eyes are checked; blast often injures both."] },
  { id: "evisc", g: 0, name: "Abdominal evisceration", line: "Bowel outside the body",
    what: "Abdominal contents pushed out through a wound.",
    why: "Exposed bowel dries, cools and loses blood supply, and contamination raises the risk of severe infection.",
    signs: ["Visible bowel or organs outside the abdomen", "Signs of internal bleeding or shock"],
    care: [["cls", "Bleeding controlled; the bowel rinsed and covered with a moist sterile or water-impermeable covering."], ["cls", "One brief attempt to replace contents only when there is no bowel leakage and bleeding is controlled; contents are not forced back."], ["cmc", "Nothing by mouth; IV or IO antibiotics; blood for shock."], ["cpp", "Pain control and evacuation to surgery."]],
    drugs: ["ceftriaxone", "ertapenem", "ketamine", "ondansetron"],
    warn: ["Hypothermia prevention matters more with exposed bowel.", "Penetrating abdominal wounds often hide non-compressible bleeding."] },
  { id: "acs", g: 3, name: "Chest pain and heart attack", line: "Acute coronary syndrome in the field",
    what: "Reduced blood flow to the heart muscle from a blocked coronary artery.",
    why: "Heart muscle without blood flow starts dying within minutes, and the injured heart can fall into deadly rhythms.",
    signs: ["Pressure-like chest pain, often to the arm, jaw or back", "Shortness of breath, sweating, nausea", "ECG changes on a 12-lead when available", "Older or high-risk service members and contractors"],
    care: [["cpp", "Monitor, 12-lead ECG when available, IV access and oxygen only if saturation is low."], ["cpp", "Aspirin for suspected acute coronary syndrome unless contraindicated."], ["cpp", "ACLS algorithms for arrhythmias; urgent evacuation to a cardiac-capable facility."]],
    drugs: ["aspirin", "epinephrine", "amiodarone", "atropine", "ondansetron"],
    warn: ["Aspirin is avoided with active bleeding or when trauma is a possible cause.", "Stimulants, dehydration and heat can trigger cardiac events in young troops too."] },
  { id: "asthma", g: 3, name: "Severe asthma attack", line: "Air goes in, but will not come out",
    what: "Severe narrowing of the airways with air trapping.",
    why: "Air trapping raises pressure in the chest, lowers blood return to the heart and tires the breathing muscles until breathing fails.",
    signs: ["Wheezing, or a silent chest in the worst cases", "Unable to speak in sentences", "Fast breathing and heart rate, low SpO2", "Exhaustion, confusion"],
    care: [["cpp", "Inhaled albuterol (salbutamol) with ipratropium; oxygen to normal saturation."], ["cpp", "Systemic steroids; magnesium for severe attacks; epinephrine when life-threatening."], ["cpp", "If ventilated: low rate, long exhale and permissive hypercapnia (low rate and long exhale)."]],
    drugs: ["albuterol", "ipratropium", "methylprednisolone", "magnesium-sulfate", "epinephrine", "ketamine"],
    warn: ["A quiet chest can mean almost no air movement.", "Smoke, burn pits and dust can trigger attacks in deployed troops."] }
);
