fmxAdd("medical", "Infection", ["pneumonia", "arboviral-fever"]);
fmxAdd("medical", "Heart and lungs", ["hypertensive-emergency"]);
fmxAdd("medical", "Brain and nerves", ["stroke"]);
fmxAdd("medical", "Abdomen, kidney and reproductive", ["acute-abdomen", "kidney-stones", "testicular-torsion", "ectopic-pregnancy"]);
