/* Long-hold drills and Drug storage tabs for Combat Paramedic & Prolonged Care (owner, Oct 29 2026). Data: fmholddata.js, fmstoredata.js. */
/* ---------- Long-hold drills ---------- */
function fmHoldDone() { try { return (Prog.d.hold = Prog.d.hold || {}); } catch (e) { return {}; } }
function fmHoldView() {
  if (typeof FM_HOLD === "undefined") return "";
  var H = S.hold, done = fmHoldDone();
  if (H && H.id) { var cs = FM_HOLD.filter(function (x) { return x.id === H.id; })[0]; if (cs) return fmHoldCase(cs); }
  var c = '<p class="fmlead">A casualty followed from point of injury through a long hold while evacuation is delayed. At each time step, pick what happens next. Every choice is explained, and the medications link to their cards.</p>';
  c += '<div class="holdlist">' + FM_HOLD.map(function (x) {
    var d = done[x.id], last = x.steps[x.steps.length - 1].at;
    return '<button class="holditem" data-hold="' + x.id + '"><strong>' + esc(x.t) + '</strong><span>' + esc(x.hook) + '</span><em>' + x.steps.length + ' steps · to ' + esc(last) + (d ? ' · best ' + d.best + '/' + x.steps.length : '') + '</em></button>';
  }).join("") + '</div>';
  return c + '<p class="muted small">Education only. Scenarios follow TCCC Guidelines and Joint Trauma System prolonged casualty care guidance; local protocols and medical direction govern care.</p>';
}
function fmHoldCase(cs) {
  var H = S.hold, i = H.i, ans = H.ans;
  var c = '<div class="backrow"><button class="backbtn" data-holdback="1"><span aria-hidden="true">&larr;</span> All drills</button></div>';
  c += '<header class="dishead"><span class="dsys">Long-hold drill</span><h2>' + esc(cs.t) + '</h2></header><div class="holdset"><p><b>Setting.</b> ' + esc(cs.setting) + '</p><p><b>Casualty.</b> ' + esc(cs.pt) + '</p></div>';
  c += '<div class="holdtl">' + cs.steps.map(function (st, k) { return '<span class="' + (k < i ? (cs.steps[k].opts[ans[k]] && cs.steps[k].opts[ans[k]][1] ? 'ok' : 'bad') : k === i ? 'cur' : '') + '">' + esc(st.at) + '</span>'; }).join("") + '</div>';
  for (var k = 0; k <= Math.min(i, cs.steps.length - 1); k++) c += fmHoldStep(cs, k, ans[k], k === i);
  if (i >= cs.steps.length) {
    var right = cs.steps.filter(function (st, k) { return st.opts[ans[k]] && st.opts[ans[k]][1]; }).length;
    c += '<section class="holdend"><h3>Outcome</h3><p>' + esc(cs.end) + '</p><p class="holdscore">' + right + ' of ' + cs.steps.length + ' best choices</p><div class="ispnav"><button class="btn small ghost" data-hold="' + cs.id + '">Run it again</button><button class="btn small" data-holdback="1">All drills</button></div></section>';
  }
  return c;
}
function fmHoldStep(cs, k, a, cur) {
  var st = cs.steps[k], answered = a != null;
  var c = '<section class="holdstep' + (cur ? ' cur' : '') + '" id="hs' + k + '"><header><span class="holdat">' + esc(st.at) + '</span><span class="holdwhere">' + esc(st.where || "") + '</span></header><p>' + esc(st.sit) + '</p>';
  if (st.vit && st.vit.length) c += '<div class="holdvit">' + st.vit.map(function (v) { return '<span><small>' + esc(v[0]) + '</small>' + esc(v[1]) + '</span>'; }).join("") + '</div>';
  if (st.labs && st.labs.length) c += '<div class="holdlabs"><small>i-STAT</small>' + st.labs.map(function (v) { return '<span class="' + (v[2] ? 'off' : '') + '">' + esc(v[0]) + ' <b>' + esc(v[1]) + '</b>' + (v[2] ? ' <em>' + (v[2] === "H" ? "high" : "low") + '</em>' : '') + '</span>'; }).join("") + '</div>';
  c += '<h4 class="isph">' + esc(st.q) + '</h4><div class="ispopts">' + st.opts.map(function (o, j) {
    var cls = !answered ? "" : o[1] ? " right" : j === a ? " wrong" : " dim";
    return '<button type="button" class="ispopt' + cls + '" data-holda="' + k + '|' + j + '"' + (answered ? ' disabled' : '') + '>' + esc(o[0]) + '</button>' + (answered && (o[1] || j === a) ? '<p class="ispexp ' + (o[1] ? 'right' : 'wrong') + '"><b>' + (o[1] ? (j === a ? "Correct. " : "Best choice: ") : "Not the best choice. ") + '</b>' + esc(o[2]) + '</p>' : '');
  }).join("") + '</div>';
  if (answered) {
    c += '<div class="ispteach"><b>Teaching point</b><p>' + esc(st.teach) + '</p></div>';
    var dr = (st.drugs || []).filter(function (d) { return DB.drugs[d]; });
    if (dr.length) c += '<div class="drugchips">' + dr.map(function (d) { return '<button class="chip" data-drug="' + d + '">' + esc(nameOf(d)) + '</button>'; }).join("") + '</div>';
    if (cur) c += '<div class="ispnav"><button class="btn small" data-holdnext="1">' + (k + 1 < cs.steps.length ? 'Continue to ' + esc(cs.steps[k + 1].at) : 'See the outcome') + '</button></div>';
  }
  return c + '</section>';
}
