var FM_STORE_F = [["", "All"], ["R", "Refrigerated"], ["rt-allow", "Room-temp allowance"], ["light", "Light-sensitive"], ["freeze", "Freezing damages"], ["heat", "Heat-sensitive"], ["reconstitute", "Mixed before use"], ["controlled", "Controlled"]];
var FM_STORE_TAGLAB = { light: "Light-sensitive", freeze: "Freezing damages it", heat: "Heat-sensitive", "rt-allow": "Room-temp allowance", reconstitute: "Mixed before use", controlled: "Controlled substance" };
function fmStoreView() {
  if (typeof FM_STORE === "undefined") return "";
  var sub = fmSub("store");
  if (sub === "quiz") sub = "learn";
  var c = fmSubBar("store", [["learn", "By drug"], ["topics", "Topics"]]);
  if (sub === "topics") return c + FM_STORE_TOPICS.map(function (x) { return '<section class="dsec"><h3><span class="dic" aria-hidden="true">' + x[1] + '</span>' + esc(x[0]) + '</h3>' + String(x[2]).split("\n").filter(Boolean).map(function (p) { return '<p>' + esc(p) + '</p>'; }).join("") + '</section>'; }).join("");
  if (sub === "quiz") return c + fmStoreQuiz();
  var f = S.stF || "", q = (S.stQ || "").trim().toLowerCase();
  var ids = Object.keys(FM_STORE).filter(function (k) { var x = FM_STORE[k]; return DB.drugs[k] && (!f || (f === "R" ? x.cold === "R" : (x.tags || []).indexOf(f) >= 0)) && (!q || (nameOf(k) + " " + x.form).toLowerCase().indexOf(q) >= 0); }).sort(function (a, b) { return nameOf(a).localeCompare(nameOf(b)); });
  c += '<p class="muted small">How each Tier 4 medication holds up in an aid bag: label storage, heat, cold, light, warning signs and what happens after mixing. Label storage is from FDA prescribing information.</p>';
  c += '<input class="pinput dissearch" id="stq" type="search" placeholder="Search a drug" aria-label="Search a drug" value="' + esc(S.stQ || "") + '">';
  c += '<div class="ispchips" role="group" aria-label="Filter">' + FM_STORE_F.map(function (x) { var n = Object.keys(FM_STORE).filter(function (k) { var y = FM_STORE[k]; return DB.drugs[k] && (!x[0] || (x[0] === "R" ? y.cold === "R" : (y.tags || []).indexOf(x[0]) >= 0)); }).length; return '<button data-stf="' + x[0] + '" aria-pressed="' + (f === x[0]) + '">' + esc(x[1]) + ' (' + n + ')</button>'; }).join("") + '</div>';
  c += '<div class="stlist">' + (ids.length ? ids.map(function (k) {
    var x = FM_STORE[k], cold = x.cold === "R" ? "Refrigerated" : x.cold === "F" ? "Frozen" : "Room temperature";
    var row = function (lab, v) { return v ? '<div class="strow"><b>' + lab + '</b><p>' + esc(v) + '</p></div>' : ''; };
    return '<details class="stitem"><summary><span class="stn"><strong>' + esc(nameOf(k)) + '</strong><small>' + esc(x.form) + '</small></span><span class="stbadge ' + x.cold + '">' + cold + '</span></summary><div class="stbody">' +
      '<div class="sttags">' + (x.tags || []).map(function (g) { return '<span>' + esc(FM_STORE_TAGLAB[g] || g) + '</span>'; }).join("") + '</div>' +
      row("Label storage", x.label) + row("Room-temperature allowance", x.rt) + row("Heat", x.heat) + row("Cold and freezing", x.coldNote) + row("Light and warning signs", x.look) + row("After mixing or drawing up", x.mixed) + row("In the field", x.field) +
      (x.src && x.src.length ? '<p class="muted small">Sources: ' + x.src.map(esc).join("; ") + '</p>' : '') + '<button class="linkish small" data-drug="' + k + '">Open the drug card</button></div></details>';
  }).join("") : '<p class="muted">No drugs match.</p>') + '</div>';
  return c + '<p class="muted small">Education only. The current label and the pharmacy that supplies the medication set storage and discard rules.</p>';
}
function fmStoreQuiz() {
  var Z = S.stz || (S.stz = { i: 0, a: -1, n: 0, ok: 0 }), Q = FM_STORE_QUIZ[Z.i % FM_STORE_QUIZ.length];
  var c = '<div class="ispbar"><span>Question ' + (Z.i % FM_STORE_QUIZ.length + 1) + ' of ' + FM_STORE_QUIZ.length + '</span><span>' + Z.ok + ' of ' + Z.n + ' correct</span></div><section class="iscase ispcase"><p class="dvpq">' + esc(Q[0]) + '</p><div class="ispopts">' + Q[1].map(function (o, j) {
    var cls = Z.a < 0 ? "" : j === Q[2] ? " right" : j === Z.a ? " wrong" : " dim";
    return '<button type="button" class="ispopt' + cls + '" data-sta="' + j + '"' + (Z.a >= 0 ? ' disabled' : '') + '>' + esc(o) + '</button>';
  }).join("") + '</div>';
  if (Z.a >= 0) c += '<div class="ispteach"><b>' + (Z.a === Q[2] ? "Correct" : "The answer: " + esc(Q[1][Q[2]])) + '</b><p>' + esc(Q[3]) + '</p></div><div class="ispnav"><button class="btn small" data-stnext="1">Next question</button></div>';
  return c + '</section>';
}
