/* Country picker on drug cards (owner, Oct 29 2026: "an option to choose another country ... show what they use the drugs for and their dosages"). Filled by fmctry1-3.js. */
window.FM_CTRY_DRUG = window.FM_CTRY_DRUG || {};
var FM_CTRY_DRUG = window.FM_CTRY_DRUG; /* shared with the lazily loaded dist/ctry.js, which runs outside this bundle */
window.FM_CTRIES = window.FM_CTRIES || [];
