  "dextrose": { inn: "Glucose", names: [["UK", "Glucose 5%, 10%, 20%, 50%"], ["Germany", "Glucose 5%, 10%, 40% (ampoules)"], ["France", "Glucosé 5%, 10%, 30%"], ["Canada", "Dextrose"], ["Australia", "Glucose 5%, 10%, 50%"], ["Israel", "Glucose; Dextrose"], ["NATO / other", "Glucose is the INN term; dextrose is common in North America"]], tip: "German emergency kits often carry 40% glucose ampoules and French 30%, so the percent printed on the label differs from U.S. D50." },
  "potassium-chloride": { inn: "Potassium chloride", names: [["UK", "Potassium chloride (premixed bags); concentrated ampoules restricted"], ["Germany", "Kaliumchlorid 7.45% (1 mmol/mL); Kalinor (oral)"], ["France", "Chlorure de potassium; Diffu-K (oral)"], ["Canada", "Potassium chloride; K-Dur (oral)"], ["Australia", "Potassium chloride; Slow-K; Span-K (oral)"], ["Israel", "Potassium chloride"], ["NATO / other", "Concentrated KCl is a high-alert medicine across NATO"]], tip: "Kaliumchlorid 7.45% and 14.9% ampoules look alike and differ twofold; concentrated KCl is a well-known high-alert medicine." },
