  gurgle: "liquid burbling",
  creak:  "a rusty hinge",
  squish: "a soft wet squeeze",
  thump:  "lub-dub",
  whoosh: "rushing air",
  zap:    "an electric crackle",
  drip:   "a slow drip",
  bubble: "fizzing",
  boing:  "a springy twang",
  rustle: "dry and papery",
  ding:   "a bright chime",
  wobble: "a jiggle",
  hum:    "a low drone",
  slosh:  "liquid moving",
  pop:    "a small pop",
  /* the ones the figure needs when you poke it (owner, Nov 4 2026) */
  thunk:  "a dull metal clang",
  crowd:  "a room full of people gasping",
  gasp:   "a sharp offended inhale",
  punch:  "a body blow",
  whine:  "a hurt complaint",
  cry:    "a wavering sob"
