      tone("sine", 196, 190, 0, 1.1, 0.1);
      tone("sine", 523, 515, 0.01, 0.85, 0.055);
      tone("sine", 782, 770, 0.01, 0.6, 0.03);
      tone("square", 88, 60, 0, 0.22, 0.07);
