        var n = Math.floor(c.sampleRate * dur), bf = c.createBuffer(1, n, c.sampleRate), dd = bf.getChannelData(0), i2;
        for (i2 = 0; i2 < n; i2++) { var u = i2 / n; dd[i2] = (Math.random() * 2 - 1) * Math.pow(u, 0.6) * (1 - u * 0.25); }
