      for (qi = 0; qi < 4; qi++) wow(1.0 + Math.random() * 0.4, 95 + Math.random() * 150, 0.85 + Math.random() * 0.45, 0.05 + Math.random() * 0.035, 0.34 + Math.random() * 0.14);
