    if (sent.t) { cur.t.n = Math.max(0, cur.t.n - sent.t.n); cur.t.c = Math.max(0, Math.min(cur.t.n, cur.t.c - sent.t.c)); }
    if (sentNight) cur.nt = Math.max(0, (cur.nt || 0) - sentNight);
