function fireFree(k) { return k === "ff1"; }
function fireLocked(k) { return !fireFree(k) && typeof PAYWALL !== "undefined" && PAYWALL && typeof isPro === "function" && !isPro(); }
function fireQs(k, mixed) { var lv = fireLv(k), set = [k].concat(mixed && lv ? lv.inc : []); return FIRE_Q.map(function (q, i) { return { i: i, q: q }; }).filter(function (x) { return set.indexOf(x.q[0]) >= 0; }); }
function fireProg() { return store("fireProg") || { lv: {}, q: {} }; }
function fireShuf(a) { a = a.slice(); for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
var FIRE_ICO = '<svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true"><path d="M12 2c1 3.5 5 5.5 5 10.5A5 5 0 0 1 7 12.5c0-2 1-3.5 2-4.5 0 2 1 3 2 3 0-3-1-5 1-9z" fill="#f97316"/><path d="M12 12c.6 1.6 2.5 2.4 2.5 4.5a2.5 2.5 0 0 1-5 0c0-1.4.8-2.2 1.4-2.8.2 1 .6 1.3 1.1 1.3 0-1.2-.4-2 0-3z" fill="#fde047"/></svg>';
function fireHomeCard() {
  if (!fireUnlocked()) return "";
  return '<h3 class="homegh">Fire science</h3><section class="routes"><div class="minis one"><button class="route rmini fireroute" data-go="fire"><span class="mtx"><h2>FireBugs <span class="pill proto">In development</span></h2><p>Firefighter I and II, then hazmat from Awareness up to Technician.</p></span><span class="mbug">' + FIRE_ICO + '</span></button></div></section>';
}
function fireView() {
  if (!fireUnlocked()) { S.view = "home"; return viewHome(); }
  var c = topbar() + '<div class="firewrap">';
  var lv = FIRE.lv && fireLv(FIRE.lv);
  if (!lv) {
    c += '<header class="pagehead"><h1>FireBugs <span class="pill proto">In development</span></h1><p>Fire science study: Firefighter I and II, then hazardous materials from Awareness to Technician. For study only. Your department\'s SOGs and your instructor come first.</p></header><section class="firelv">';
    var P = fireProg();
    FIRE_LV.forEach(function (l, ix) {
      if (ix === 2) c += '<h3 class="homegh">Hazardous materials</h3>';
      if (ix === 0) c += '<h3 class="homegh">Firefighter</h3>';
      var n = fireQs(l.k).length, b = P.lv[l.k] && P.lv[l.k].best;
      c += '<button class="firecard" data-fire-lv="' + l.k + '"><span class="fcn">' + esc(l.n) + (fireLocked(l.k) ? ' <span class="lockpill">Pro</span>' : fireFree(l.k) ? ' <span class="pill">Free</span>' : '') + '</span><span class="fcd">' + esc(l.d) + '</span><span class="fcm">' + n + ' questions' + (b != null ? ' · best ' + b + '%' : '') + '</span></button>';
    });
    c += '</section><p class="muted small">Questions are written by DrugBug from firefighter and hazmat responder job tasks. They are not copied from NFPA standards or textbook publishers, and they are being reviewed with fire science instructors. Spot a problem? <button class="linkbtn" data-report="FireBugs question problem: ">Report it</button></p>';
    return c + '</div>';
  }
  c += '<header class="pagehead"><button class="btn small ghost" data-fire-back="1">← FireBugs</button><h1>' + esc(lv.n) + '</h1><p>' + esc(lv.d) + '</p></header>';
  c += '<nav class="settabs" role="tablist">' + [["study", "Study"], ["quiz", "Quiz"]].map(function (t) { return '<button role="tab" data-fire-tab="' + t[0] + '" aria-selected="' + (FIRE.tab === t[0]) + '">' + t[1] + '</button>'; }).join("") + '</nav>';
  if (FIRE.tab === "quiz") c += fireQuizHTML(lv); else c += fireStudyHTML(lv);
  return c + '</div>';
}
function fireStudyHTML(lv) {
  var by = {}, order = [];
  fireQs(lv.k).forEach(function (x) { var t = x.q[1]; if (!by[t]) { by[t] = []; order.push(t); } by[t].push(x.q); });
  return '<section class="firestudy">' + order.map(function (t) {
    return '<details class="firetopic"><summary>' + esc(t) + ' <span class="muted">(' + by[t].length + ')</span></summary><ul>' + by[t].map(function (q) { return '<li><strong>' + esc(q[2]) + '</strong><br>' + esc(q[3]) + '. <span class="muted">' + esc(q[7]) + '</span></li>'; }).join("") + '</ul></details>';
  }).join("") + '</section>';
}
function fireQuizHTML(lv) {
  var Z = FIRE.quiz;
  if (!Z || Z.lv !== lv.k) {
    var mix = lv.inc.length ? '<button class="btn" data-fire-start="mix">Mixed review: ' + esc(lv.n) + ' and the levels before it</button>' : '';
    return '<section class="firequiz"><p>Rounds of 10 questions. You see the explanation after each answer.</p><div class="actions"><button class="btn" data-fire-start="lv">Quiz ' + esc(lv.n) + '</button>' + mix + '</div></section>';
  }
  if (Z.i >= Z.list.length) {
    var pct = Math.round(100 * Z.c / Z.list.length);
    return '<section class="firequiz"><h2>' + Z.c + ' of ' + Z.list.length + ' right (' + pct + '%)</h2><div class="actions"><button class="btn" data-fire-start="' + (Z.mix ? "mix" : "lv") + '">Another round</button><button class="btn ghost" data-fire-tab="study">Study</button></div></section>';
  }
  var it = Z.list[Z.i], q = it.q;
  var h = '<section class="firequiz"><p class="muted small">Question ' + (Z.i + 1) + ' of ' + Z.list.length + ' · ' + esc(q[1]) + '</p><h2 class="fireq">' + esc(q[2]) + '</h2><div class="fireopts">';
  h += it.opts.map(function (o, j) {
    var cls = Z.pick == null ? "" : (o === q[3] ? " right" : (j === Z.pick ? " wrong" : ""));
    return '<button class="fireopt' + cls + '" data-fire-pick="' + j + '"' + (Z.pick != null ? " disabled" : "") + '>' + esc(o) + '</button>';
  }).join("") + '</div>';
  if (Z.pick != null) h += '<div class="presult ' + (it.opts[Z.pick] === q[3] ? "good" : "") + '" role="status"><strong>' + (it.opts[Z.pick] === q[3] ? "Right." : "Not quite. The answer is: " + esc(q[3]) + ".") + '</strong> ' + esc(q[7]) + '</div><div class="actions"><button class="btn" data-fire-next="1">' + (Z.i + 1 < Z.list.length ? "Next" : "See score") + '</button><button class="btn ghost small" data-report="FireBugs ' + esc(q[0]) + ': ' + esc(q[2].slice(0, 80)) + '">Report this question</button></div>';
  return h + '</section>';
}
function fireStart(mix) {
  var lv = fireLv(FIRE.lv), P = fireProg();
  var pool = fireQs(lv.k, mix).map(function (x) { var r = P.q[x.i] || { n: 0, c: 0 }; return { x: x, w: r.n === 0 ? 2 : (r.c < r.n ? 3 : 1) + Math.random() }; });
  pool.sort(function (a, b) { return b.w + Math.random() - (a.w + Math.random()); });
  FIRE.quiz = { lv: lv.k, mix: mix, i: 0, c: 0, pick: null, list: pool.slice(0, 10).map(function (p) { var q = p.x.q; return { i: p.x.i, q: q, opts: fireShuf([q[3], q[4], q[5], q[6]]) }; }) };
}
document.addEventListener("click", function (e) {
  if (S.view !== "fire") return;
  var t = e.target.closest("[data-fire-lv],[data-fire-back],[data-fire-tab],[data-fire-start],[data-fire-pick],[data-fire-next]"); if (!t) return;
  e.stopImmediatePropagation(); e.preventDefault();
  var a = t.dataset;
  if (a.fireLv) { if (fireLocked(a.fireLv)) return openPaywall("FireBugs: " + fireLv(a.fireLv).n, "pro"); FIRE.lv = a.fireLv; FIRE.tab = "study"; FIRE.quiz = null; }
  else if (a.fireBack) { FIRE.lv = null; FIRE.quiz = null; }
  else if (a.fireTab) { FIRE.tab = a.fireTab; if (a.fireTab === "study") FIRE.quiz = null; }
  else if (a.fireStart) { fireStart(a.fireStart === "mix"); }
  else if (a.firePick != null && FIRE.quiz && FIRE.quiz.pick == null) {
    var Z = FIRE.quiz, it = Z.list[Z.i], ok = it.opts[+a.firePick] === it.q[3], P = fireProg();
    Z.pick = +a.firePick; if (ok) Z.c++;
    var r = P.q[it.i] || { n: 0, c: 0 }; r.n++; if (ok) r.c++; P.q[it.i] = r;
    if (Z.i + 1 >= Z.list.length) { var pct = Math.round(100 * Z.c / Z.list.length), L = P.lv[Z.lv] || {}; L.best = Math.max(L.best || 0, pct); L.rounds = (L.rounds || 0) + 1; P.lv[Z.lv] = L; }
    store("fireProg", P);
  }
  else if (a.fireNext) { FIRE.quiz.i++; FIRE.quiz.pick = null; }
  render(); if (!a.firePick) window.scrollTo(0, 0);
}, true);
