  var rest = Object.keys(open).concat(Object.keys(lock)).filter(function (id) { return !seen[id]; });
  if (rest.length) G.push({ key: "", name: "More medications", gi: 6, ids: rest.sort(function (a, b) { return nameOf(a) < nameOf(b) ? -1 : 1; }) });
  G = G.filter(function (x) { return x.ids.length; });
  G.forEach(function (x) {
    x.ids.sort(function (a, b) { return (lock[a] ? 1 : 0) - (lock[b] ? 1 : 0); });
    x.ids.forEach(function (id) { cells.push([id, x.gi]); });
    var mine = x.ids.filter(function (id) { return !lock[id]; }); x.pct = masteryPct(mine); x.open = mine.length;
  });
  var ids = cells.map(function (x) { return x[0]; }).filter(function (id) { return !lock[id]; });
