  c += '<div class="hvsay"><span class="hvbug">' + art + '</span><p><b>Hickory:</b> ' + line + '</p></div>';
  c += '<div class="hvbtns">' + (weakG ? '<button class="btn" data-sess="sys" data-sys="' + weakG.key + '">Quiz ' + esc(weakG.name.split(/ & |, /)[0]) + '</button>' : '') + '<button class="btn ghost" data-act="lrngo">Learn one by one</button></div>';
