  var st = document.createElement("style");
  st.textContent = ".csn{margin:14px 0;padding:14px;border-radius:16px;border:1.5px solid var(--line);background:var(--surface)}.csnhd{display:flex;flex-wrap:wrap;gap:4px 10px;align-items:baseline;margin-bottom:10px}.csnhd b{font-size:16px}.csnhd span{color:var(--muted);font-size:13px}" +
    ".csnlist{display:grid;gap:8px}.csnpick{display:flex;justify-content:space-between;gap:10px;align-items:center;text-align:left;padding:12px 14px;border-radius:12px;border:1px solid var(--line);background:var(--surface-2,rgba(127,127,127,.08));color:inherit;font:inherit;cursor:pointer}.csnpick span{color:var(--muted);font-size:12.5px;white-space:nowrap}";
